// swift-tools-version: 5.9
//
// MLX-Swift port of NVIDIA Nemotron 3.5 ASR streaming (cache-aware
// FastConformer-RNNT, 40 language-locales), mirroring the Python reference in
// Blaizzy/mlx-audio `mlx_audio/stt/models/nemotron_asr/`. Module/file names track
// the reference for 1:1 parity diffing. Weights: mlx-community/nemotron-3.5-asr-streaming-0.6b.
//
// The slaney 128-mel filterbank is a BAKED resource (generated by the Python
// oracle, PORTING/oracle) per the mlx-audio-dsp "bake fixed transforms" rule.
//
import PackageDescription

let package = Package(
    name: "NemotronASR",
    platforms: [
        .macOS(.v14),
        .iOS(.v17),
        .visionOS(.v1),
    ],
    products: [
        .library(name: "NemotronASR", targets: ["NemotronASR"]),
        .executable(name: "nemotron-gate", targets: ["nemotron-gate"]),
    ],
    dependencies: [
        .package(url: "https://github.com/ml-explore/mlx-swift", from: "0.25.0"),
        .package(url: "https://github.com/apple/swift-argument-parser", from: "1.3.0"),
        // Shared STFT/mel primitives (windows, framing, spectra, filterbank apply).
        .package(url: "https://github.com/xocialize/mlx-audio-dsp.git", from: "0.1.0"),
    ],
    targets: [
        .target(
            name: "NemotronASR",
            dependencies: [
                .product(name: "MLX", package: "mlx-swift"),
                .product(name: "MLXNN", package: "mlx-swift"),
                .product(name: "MLXFFT", package: "mlx-swift"),
                .product(name: "MLXFast", package: "mlx-swift"),
                .product(name: "MLXRandom", package: "mlx-swift"),
                .product(name: "MLXAudioDSP", package: "mlx-audio-dsp"),
            ],
            resources: [.copy("Resources/mel_filters_slaney_128.safetensors")]
        ),
        .executableTarget(
            name: "nemotron-gate",
            dependencies: [
                "NemotronASR",
                .product(name: "ArgumentParser", package: "swift-argument-parser"),
            ]
        ),
        .testTarget(
            name: "NemotronASRTests",
            dependencies: ["NemotronASR"]
        ),
    ]
)
